$delegates=@{};foreach($name in $plan.types){$native=[type]::GetType($name,$true);foreach($route in @('string','chars','bytes')){foreach($trying in @($false,$true)){$inputType=[string];if($route -ne 'string'){$element=[char];if($route -eq 'bytes'){$element=[byte]};$inputType=[ReadOnlySpan``1].MakeGenericType($element)};$types=[type[]]@($inputType,[Globalization.NumberStyles],[IFormatProvider]);if($trying){$types=[type[]]@($inputType,[Globalization.NumberStyles],[IFormatProvider],$native.MakeByRefType())};$method=$native.GetMethod($(if($trying){'TryParse'}else{'Parse'}),$types);$dm=[Reflection.Emit.DynamicMethod]::new('IntegerZero',[object],[type[]]@([object],[int],[IFormatProvider],[Array]));$il=$dm.GetILGenerator();$op=[Reflection.Emit.OpCodes];$il.Emit($op::Ldarg_0);if($route -eq 'bytes'){$il.Emit($op::Castclass,[byte[]]);$il.Emit($op::Newobj,$inputType.GetConstructor([type[]]@([byte[]])))}else{$il.Emit($op::Castclass,[string]);if($route -eq 'chars'){$il.Emit($op::Call,[MemoryExtensions].GetMethod('AsSpan',[type[]]@([string])))}};$il.Emit($op::Ldarg_1);$il.Emit($op::Ldarg_2);if($trying){$il.Emit($op::Ldarg_3);$il.Emit($op::Castclass,$native.MakeArrayType());$il.Emit($op::Ldc_I4_0);$il.Emit($op::Ldelema,$native)};$il.Emit($op::Call,$method);if($trying){$il.Emit($op::Box,[bool])}else{$il.Emit($op::Box,$native)};$il.Emit($op::Ret);$delegates["$name/$route/$trying"]=$dm.CreateDelegate([Func[object,int,IFormatProvider,Array,object]])}}}
